/* eslint-disable @typescript-eslint/ban-ts-comment */
import React, { FormEvent } from 'react';

import notificationHelper from '@helpers/notificationHelper';
import PohAlert from '@ui-kit/Alert';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import PohLoader from '@ui-kit/Loader';

import {
  IMedicament,
  IMedicamentCategory,
  IMedicamentForm,
} from '../../../Medicaments/@types/medicaments.types';
import {
  addMedicamentsCategoryAsync,
  addMedicamentsFormAsync,
  getMedicamentsAsync,
  getMedicamentsCategoriesAsync,
  getMedicamentsFormsAsync,
} from '../../../Medicaments/services/medicaments.services';

interface IMedicamentModalProps {
  onAdd?: (selected: Omit<IMedicament, 'id'>) => void;
  onEdit?: (selected: IMedicament) => void;
  onCancel: () => void;
  data?: IMedicament;
}

const MedicamentModal: React.FC<IMedicamentModalProps> = ({ data, onAdd, onEdit }) => {
  const [isLoading, setIsLoading] = React.useState(false);
  const [err, setErr] = React.useState<string>('');
  const [medicaments, setMedicaments] = React.useState<IMedicament[]>([]);
  const [categories, setCategories] = React.useState<IMedicamentCategory[]>([]);
  const [forms, setForms] = React.useState<IMedicamentForm[]>([]);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        setMedicaments(await getMedicamentsAsync());
        setCategories(await getMedicamentsCategoriesAsync());
        setForms(await getMedicamentsFormsAsync());
      } catch (e) {
        setErr((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, []);

  if (isLoading) {
    return <PohLoader />;
  }

  if (err.length) {
    return <PohAlert>{err}</PohAlert>;
  }

  const medicamentsInCategoriesMap: Record<string, IMedicament[]> = {};
  medicaments.map((m) => {
    const k = (m.category?.name ?? 'Без категории') as string;
    if (!medicamentsInCategoriesMap[k]) {
      medicamentsInCategoriesMap[k] = [];
    }
    medicamentsInCategoriesMap[k].push(m);
  });

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const el = e.target as HTMLFormElement;

    // @ts-ignore
    const name = el.elements.name.value;
    // @ts-ignore
    const category = el.elements.category.value;
    // @ts-ignore
    const form = el.elements.form.value;
    // @ts-ignore
    const dosage = el.elements.dosage.value;
    // @ts-ignore
    const usages = el.elements.usages.value;
    // @ts-ignore
    const contraindications = el.elements.contraindications.value;

    const patch: Omit<IMedicament, 'id'> = {
      name,
      form: {
        id: +form,
        name: forms.find((f) => f.id === form)?.name ?? '',
      },
      category: {
        id: +category,
        name: categories.find((f) => f.id === category)?.name ?? '',
      },
      dosage,
      usages,
      contraindications,
    };

    data
      ? onEdit?.({
          ...data,
          ...patch,
        })
      : onAdd?.(patch);
  };

  const handleAddForm = () => {
    const name = prompt('Добавление новой формы выпуска');
    if (!name) {
      return;
    }
    addMedicamentsFormAsync(name).then((newForm) => {
      notificationHelper.success('Добавлена форма выпуска: ' + newForm.name);
      setForms((a) => [...a, newForm]);
      const sel = document.querySelector<HTMLSelectElement>(`select[name='form']`);
      if (sel) {
        sel.value = newForm.id.toString();
      }
    });
  };

  const handleAddCategory = () => {
    const name = prompt('Добавление новой категории');
    if (!name) {
      return;
    }
    addMedicamentsCategoryAsync(name).then((newCategory) => {
      notificationHelper.success('Добавлена категория: ' + newCategory.name);
      setCategories((a) => [...a, newCategory]);
      const sel = document.querySelector<HTMLSelectElement>(`select[name='category']`);
      if (sel) {
        sel.value = newCategory.id.toString();
      }
    });
  };

  return (
    <form onSubmit={handleSubmit}>
      <div className="mb-3">
        <label className="form-label">Название</label>
        <input name="name" defaultValue={data?.name} className="form-control" required autoFocus />
      </div>
      <div className="row mb-3">
        <div className="col-sm-6">
          <label className="form-label  d-flex align-items-end justify-content-between">
            Категория
            <PohButton size={ButtonSize.Small} onClick={handleAddCategory}>
              +
            </PohButton>
          </label>
          <select className="form-control" name="category" defaultValue={data?.category?.id}>
            {categories.map((x) => (
              <option key={x.id} value={x.id}>
                {x.name}
              </option>
            ))}
          </select>
        </div>
        <div className="col-sm-6">
          <label className="form-label d-flex align-items-end justify-content-between">
            Форма выпуска{' '}
            <PohButton size={ButtonSize.Small} onClick={handleAddForm}>
              +
            </PohButton>
          </label>
          <select className="form-control" name="form" defaultValue={data?.form?.id}>
            {forms.map((x) => (
              <option key={x.id} value={x.id}>
                {x.name}
              </option>
            ))}
          </select>
        </div>
      </div>
      <div className="mb-3">
        <label className="form-label">Дозировка</label>
        <input name="dosage" defaultValue={data?.dosage} className="form-control" required />
      </div>
      <div className="mb-3">
        <label className="form-label">Показания к применению</label>
        <textarea
          rows={2}
          name="usages"
          defaultValue={data?.usages}
          className="form-control"
          required
        />
      </div>
      <div className="mb-3">
        <label className="form-label">Противопоказания</label>
        <textarea
          rows={2}
          name="contraindications"
          defaultValue={data?.contraindications}
          className="form-control"
          required
        />
      </div>
      <footer className="text-end">
        <button type="submit" className="btn btn-primary mt-3 ms-auto">
          {data ? 'Сохранить' : 'Добавить'}
        </button>
      </footer>
    </form>
  );
};

export default MedicamentModal;
